    // ownership.
    var inside = RunGit(repoRoot, ["rev-parse", "--is-inside-work-tree"]);
    if (inside.ExitCode != 0
        || !string.Equals(inside.StandardOutput.Trim(), "true", StringComparison.Ordinal))
